def detect_crop_top(
    page: fitz.Page,
    scale: float,
    left: float,
    right: float,
    first_question_y: float,
    pad: float = 8.0,
) -> float:
    """Crop top just above the first question, below any leaked header line."""
    default_top = max(0.0, first_question_y - pad)
    search_top = max(0.0, first_question_y - 55.0)
    if first_question_y - search_top < 10:
        return default_top
    pixmap = page.get_pixmap(matrix=fitz.Matrix(scale, scale), alpha=False)
    image = Image.frombytes("RGB", (pixmap.width, pixmap.height), pixmap.samples)
    crop = image.crop(
        (
            int(left * scale),
            int(search_top * scale),
            int(min(right, page.rect.width) * scale),
            int(first_question_y * scale),
        )
    )
    if crop.height < 4 or crop.width < 8:
        del image, pixmap
        return default_top
    pixels = crop.load()
    # Row is "inky" if enough dark pixels (header / instructions).
    min_dark = max(6, int(crop.width * 0.02))
    ink_rows: list[bool] = []
    for y in range(crop.height):
        dark = 0
        for x in range(0, crop.width, 2):
            red, green, blue = pixels[x, y]
            if (red + green + blue) / 3.0 < 200:
                dark += 1
                if dark >= min_dark:
                    break
        ink_rows.append(dark >= min_dark)
    # Last inky row in this band is the bottom of the header leak.
    last_ink = None
    for index, is_ink in enumerate(ink_rows):
        if is_ink:
            last_ink = index
    del crop, image, pixmap
    gc.collect()
    if last_ink is None:
        return default_top
    header_bottom = search_top + (last_ink + 1) / scale
    # Only treat it as a header if it sits clearly above the question number.
    if header_bottom < first_question_y - 6.0:
        return min(default_top, max(0.0, header_bottom + 2.0))
    return default_top


def load_overrides(path: Path | None) -> dict[int, tuple[int, float, float]]:
    if path is None:
        return {}
    raw = json.loads(path.read_text())
    return {int(k): (int(v[0]), float(v[1]), float(v[2])) for k, v in raw.items()}

