  \node[font=\scriptsize,above] at (3.4,2.6) {$Q$};
  \draw[{Latex}-{Latex}] (1.2,2) -- (3.4,2)
    node[midway,below,font=\scriptsize] {p.d.\ $V_{PQ}=6\,\mathrm{V}$};
\end{circuitikz}
\end{center}

