In the circuit below, each bulb dissipates $2\,\mathrm{J}$ per coulomb of charge;
each resistor dissipates $4\,\mathrm{J}$ per coulomb.
What are the p.d.s between (a)~points $A$ and $B$, and (b)~points $C$ and $D$?
\begin{center}
\begin{circuitikz}[scale=1.05, transform shape]
  \draw (5.2,3.0) to[battery1, l_=$6\,\mathrm{V}$] (0,3.0);
  \draw (0,3.0) -- (0,0) -- (5.2,0) -- (5.2,3.0);
  % upper branch: bulb, C, R
  \draw (0,2.2) to[bulb] (2.4,2.2)
        to[R] (5.2,2.2);
  \node[circ] at (0,2.2) {};
  \node[font=\scriptsize,left] at (-0.1,2.2) {$A$};
  \node[circ] at (2.4,2.2) {};
  \node[font=\scriptsize,below] at (2.4,2.2) {$C$};
  % lower branch: R, D, bulb
  \draw (0,0.8) to[R] (2.4,0.8)
        to[bulb] (5.2,0.8);
  \node[circ] at (0,0.8) {};
  \node[font=\scriptsize,left] at (-0.1,0.8) {$B$};
  \node[circ] at (2.4,0.8) {};
  \node[font=\scriptsize,below] at (2.4,0.55) {$D$};
\end{circuitikz}
\end{center}
\sol[3.2cm]{%
