  \draw[thick,red!75!black] (1.6,3.4) -- (1.6,2.7);
  \draw[thick,red!75!black] (3.8,3.4) -- (3.8,2.7);
  \draw (1.6,2.7) to[R, l=$3\,\Omega$] (1.6,0.7);
  \draw (3.8,2.7) to[R, l=$6\,\Omega$] (3.8,0.7);
  \draw[thick,blue!70!black] (1.6,0.7) -- (1.6,0) -- (5.2,0) -- (0,0) -- (0,0.9);
  \draw[thick,blue!70!black] (3.8,0.7) -- (3.8,0);
  \node[font=\scriptsize,red!75!black] at (2.6,3.65) {same potential ($6\,\mathrm{V}$)};
  \node[font=\scriptsize,blue!70!black] at (2.6,-0.4) {same potential ($0$)};
\end{circuitikz}
\end{center}

Both resistors join the \emph{same} red node and blue node $\Rightarrow$ they are in parallel
(same p.d.\ $=6\,\mathrm{V}$ across each) --- read this from the colours, not from $1/R_{\mathrm{eq}}$.

