  \draw (0.5,1.2) to[R, l_=$6\,\Omega$] (3.0,1.2) node[circ]{} node[below,font=\scriptsize] {$B$}
        to[R, l_=$6\,\Omega$] (5.5,1.2);
  \draw (0.5,2.8) -- (0.5,1.2);
  \draw (5.5,2.8) -- (5.5,1.2);
  \draw (0.5,1.2) -- (0.5,0) to[battery1, l_=$\mathcal{E}$] (5.5,0) -- (5.5,1.2);
  \draw[{Latex}-{Latex}] (3.0,1.35) -- (3.0,2.65)
    node[midway,right,font=\scriptsize] {$1\,\mathrm{V}$};
\end{circuitikz}
